WITH left_oracle AS (SELECT mktcode,tgtcode,bizdate FROM `newzl`.`hsj_stock_hq_basic_technical` WHERE bizdate='2026-04-14' AND ABS(ma5-ma20)/NULLIF(GREATEST(ABS(ma5),ABS(ma20)),0)<=0.03), right_oracle AS (WITH w AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx/10000.0 AS px,t.ma30,LAG(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS ppx,LAG(t.ma30) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS pma FROM `newzl`.`hsj_stock_hq_basic` AS b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` AS t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px<ma30 AND ppx>=pma), left_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM left_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=1), right_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM right_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode IN (0,1) AND q.volume>=100) SELECT mktcode,tgtcode,bizdate FROM left_filtered UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM right_filtered;
